"""Targeted DOCX revision preserving equations, unaffected figures and styles."""
from pathlib import Path
from copy import deepcopy
from zipfile import ZipFile
import shutil,json,hashlib,re
from docx import Document
from docx.shared import Inches,Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn
from lxml import etree

ROOT=Path('C:/work/ls4t-msg/cases/official/results/production_assessment/manuscript_validation_update')
SOURCE=Path('C:/BaiduSyncdisk/research/ls4t_msg/LS4T-MSG-v6-revised.docx')
OUTPUT=ROOT/'revised'/SOURCE.name

def replace(p,text):
    rp=deepcopy(p.runs[0]._r.rPr) if p.runs and p.runs[0]._r.rPr is not None else None
    p.clear();r=p.add_run(text)
    if rp is not None:r._r.insert(0,rp)

def main():
    backup=ROOT/'backup'/SOURCE.name;backup.parent.mkdir(parents=True,exist_ok=True)
    if not backup.exists():shutil.copy2(SOURCE,backup)
    doc=Document(backup);original=Document(backup)
    before=[etree.tostring(e) for e in doc._element.xpath('.//m:oMath')]
    facts=json.loads((ROOT/'validation_facts.json').read_text(encoding='utf8'))
    texts={
7: 'Abstract. Satellite land surface temperature (LST) combines vegetation and soil contributions, limiting its interpretation over heterogeneous surfaces. LS4T-MSG describes monthly vegetation-canopy and background-soil temperatures from paired Meteosat Second Generation observations of the European and Indian Ocean services. The archive contains 707 files for August 2017–December 2025 at seven nominal UTC hours (10:00–16:00) on a nominal 0.03° grid; inputs begin on 3 August 2017. A constrained sequential neighborhood estimate supplies the target for a regularized joint adjustment of canopy, sunlit-soil and shaded-soil radiances. Background-soil temperature is derived by combining the soil radiances and inverting the Planck function. Station evaluations use monthly means calculated separately at each hour from 11:00 to 16:00 UTC, after joint 0–60 °C and 10 K retrieval–reference screening. At Évora (EVO), sunlit-soil and canopy RMSEs are 1.883 and 3.427 K across 30 month–hour pairs during August–December 2017. Background soil compared with the same sunlit-soil radiometry gives 2.929 K; this is a cross-component comparison, not direct background-soil validation. At 12 European stations during 2018–2024, mean station RMSEs are 4.014 K for shaded soil against soil probes and 3.626 K for canopy against air temperature. These conditional, indirect comparisons use a post hoc station subset and do not establish regional product accuracy. Station estimates use a corrected physical implementation that differs from the archived regional configuration. Input decoding, viewing geometry, sampling metadata and station-time alignment remain limitations. Illustrative 2018–2025 area-weighted analyses show no statistically significant trend.',
28: 'The evaluation combines 2017 component radiometry at EVO near Évora, Portugal, with meteorological measurements from European stations during 2018–2024. SI-111 thermal radiometers at EVO observe canopy and sunlit-soil targets in open woodland (Martin et al., 2019). Its August–December 2017 record overlaps the first product months. The evaluated estimates are calculated directly from cached station inputs rather than extracted from the regional monthly grids (Table 2). Table 1 lists the 12 European stations retained for the principal indirect comparison. This subset excludes IT-TrF and FR-EM2 after inspection of the 14-station results; the exclusion is a post hoc analysis choice, not evidence of instrument failure. Results for all 14 European stations are retained as a sensitivity comparison. CD-Ygb is outside this European evaluation and appears only in the earlier numerical replay tests of Sect. 4.4.',
29: 'EVO sunlit-soil and canopy radiometry provide component-specific references, subject to footprint representativeness. Retrieved background-soil temperature is additionally compared with the same sunlit-soil reference to quantify their difference; no independent background-soil radiometry is available. In Europe, shaded-soil temperature is compared with TS_1 soil-probe temperature, and canopy temperature with TA air temperature. Probe depth and air-measurement height vary by source and are not replaced by surface radiometric temperatures. These comparisons therefore assess indirect consistency rather than absolute component accuracy (Jia et al., 2003; Menenti et al., 2001; Op de Beeck et al., 2018; Rebmann et al., 2018; Heiskanen et al., 2022). Both domains use 11:00–16:00 UTC and month–hour means, while their periods and physical reference quantities remain different.',
30: 'Table 1. The 12 European meteorological stations used for the principal indirect comparisons in Sect. 4.3. IT-TrF and FR-EM2 are excluded from this post hoc subset; the complete 14-station results are reported as a sensitivity comparison.',
59: 'The isotropic form uses C_D = σ²I₂ and C_M = (σ²/λ)I₃, giving m = (WᵀW + λI₃)⁻¹(WᵀL + λmₚ). Here σ² has squared-radiance units and λ is a dimensionless relative penalty; the common σ² factor cancels from this point estimate. The regional configuration uses λ = 100 without calibrating an absolute observation-error variance. The corrected station evaluation uses λ = 1000, hotspot parameter 0.25, δ = 3 W m⁻² sr⁻¹ μm⁻¹ and 5 × 5 windows at both stages. It evaluates the center pixel, restores signed LST values, uses consistent physical Planck units and a common valid-input mask, and requires at least 10 valid paired neighbors and center LAI ≥ 0.05. All four station outputs must be finite and within 250–350 K before the additional reference-based evaluation filters are applied. For a singular value s of W, the residual-to-update gain is s/(s² + λ); this is an analytical radiance-space gain, not an observed temperature change. After the linear update, shaded-soil radiance is capped at sunlit-soil radiance, so the capped state need not minimize the unconstrained objective in Eq. (6). No normalized-residual or condition-number screening is applied. The historical raw-output replay in Sect. 4.4 is distinct from this corrected station evaluation.',
66: 'Table 2. Archived regional configuration and corrected station-evaluation settings. The validation figures use the same station configuration, whereas the 707-file regional archive retains its earlier production configuration.',
75: 'The August 2017 EVO example resolves monthly mean temperatures at each hour from 11:00 to 16:00 UTC (Fig. 5). Sunlit soil, background soil and canopy are shown separately. Both soil panels use the measured sunlit-soil temperature as their reference; the background-soil panel therefore illustrates a difference between thermal definitions. The canopy panel uses the sunlit-soil/canopy joint sample. Means, sample standard deviations and pair counts are calculated from the retained instantaneous pairs using the same filters as Sect. 4.2. These station-scale estimates are not extracted from the regional monthly grids.',
77: 'Figure 5. EVO monthly mean temperatures at each UTC hour in August 2017: sunlit soil, background soil and canopy. Blue circles show corrected radiometry, colored squares station retrievals and gray triangles bulk LST. Both soil panels use sunlit-soil radiometry; the canopy panel uses canopy radiometry on the sunlit-soil/canopy joint sample. Error bars are ±1 sample standard deviation for radiometry and retrievals; numbers are retained instantaneous pair counts. Joint 0–60 °C and 10 K screening precedes averaging. The background-soil panel is a cross-component comparison.',
79: 'The EVO evaluation uses the corrected station configuration in Table 2 and radiometry matched at identical UTC timestamps. Available inputs span 3 August–30 December 2017, and the principal comparison uses 11:00–16:00 UTC. Radiometry is corrected at 10.5 × 10⁻⁶ m with emissivity 0.985 and sky temperature 250 K. For each soil scheme, the chosen soil estimate, canopy estimate, corresponding soil and canopy references, and bulk LST must all lie within 0–60 °C. Both instantaneous absolute retrieval–reference differences must be ≤10 K; if either fails, the timestamp is removed for both components. This threshold is an evaluation filter using reference observations, not a product quality flag. After screening, paired means are computed separately for each calendar year, month and UTC hour, with at least three instantaneous pairs per group. Hours are not pooled within a month. The sunlit-soil/canopy scheme yields 30 month–hour pairs from 528 instantaneous pairs; the background-soil/canopy scheme yields 30 from 526. The main canopy result uses the sunlit-soil scheme. Statistics without the residual filter are retained in Sect. 5.1.',
80: 'For the month–hour pairs in Fig. 6, sunlit-soil and canopy RMSEs are 1.883 and 3.427 K, with signed biases of −0.670 and +2.647 K. Background soil compared with the sunlit-soil radiometry gives RMSE 2.929 K and bias −2.156 K. The canopy RMSE on the background-soil scheme’s slightly different sample is 3.408 K. Bulk-LST RMSEs on the identical pairs are 4.563 K against sunlit-soil radiometry and 9.643 K against canopy radiometry in the main scheme, and 4.561 K against sunlit-soil radiometry in the background scheme. Because the residual filter uses component errors, these bulk comparisons do not constitute an unbiased algorithm ranking. All scores describe the retained station-mode samples rather than the accuracy of the regional archive. The background comparison cannot establish background-soil accuracy because the reference observes a different soil component.',
82: 'Figure 6. EVO comparisons of monthly means at each hour from 11:00 to 16:00 UTC during August–December 2017. Panels show (a) sunlit soil against sunlit-soil radiometry, (b) background soil against the same type of sunlit-soil reference, and (c) canopy against canopy radiometry. Each panel contains 30 month–hour pairs; panels (a) and (c) use 528 instantaneous pairs, and panel (b) uses 526. Colored circles show component estimates and gray triangles bulk LST on the same pairs; dashed lines are 1:1. The joint range and residual filters in Sect. 4.2 are applied before averaging. Bias is estimated minus reference temperature. Panel (b) is a cross-component diagnostic, not direct background-soil validation.',
83: 'Figure 7 evaluates hourly variation in RMSE using the same month–hour pairs as Fig. 6. Each hour from 11:00 to 16:00 UTC contains five monthly pairs, with no pooling across hours. Sunlit soil and canopy are evaluated against their respective radiometry, while background soil is compared with sunlit-soil radiometry. The small number of monthly pairs and the single-site setting preclude interpreting an individual hourly score as a spatially uniform product-accuracy threshold.',
85: 'Figure 7. Hour-specific RMSE at EVO calculated from the month–hour pairs in Fig. 6. Each UTC hour has five monthly pairs. Colored curves represent sunlit-soil, background-soil and canopy retrievals in their respective panels; gray curves show bulk LST on identical pairs. The background-soil reference is sunlit-soil radiometry. Joint 0–60 °C and 10 K screening precedes monthly averaging; these are conditional errors on the retained samples.',
87: 'Figure 8 evaluates corrected station-mode predictions at the 12 European sites in Table 1 during 2018–2024. The station configuration is identical to that used at EVO: hotspot parameter 0.25, λ = 1000, δ = 3 W m⁻² sr⁻¹ μm⁻¹ and 5 × 5 windows at both stages. Shaded-soil temperature is compared with TS_1 and canopy temperature with TA at 11:00–16:00 UTC. Shaded-soil, canopy, both references and bulk LST must be within 0–60 °C, and both instantaneous component–reference absolute differences must be ≤10 K. The two components share all retained timestamps. Means are formed separately for each year, month and hour, requiring at least three paired observations per group and three groups per station. The resulting 778 station–month–hour pairs use 5472 instantaneous pairs. Mean station RMSE is 4.014 K for shaded soil and 3.626 K for canopy; corresponding bulk-LST values on the same pairs are 8.033 and 4.346 K. The component-based residual filter conditions this comparison. Station RMSEs are averaged with equal station weights. FI-Hyy contributes only five groups and 16 instantaneous pairs, limiting the representativeness of its score.',
89: 'Figure 8. Indirect month–hour comparisons at 12 European stations during 2018–2024, restricted to 11:00–16:00 UTC. Shaded soil is compared with soil-probe temperature (upper panel), and canopy with air temperature (lower panel). Colored bars show component RMSE and gray bars bulk-LST RMSE on identical retained pairs. Labels give station–month–hour group counts. Joint 0–60 °C and 10 K filters are applied to instantaneous observations before averaging. Across-station mean component RMSEs are 4.014 and 3.626 K, respectively. The station subset was selected after inspecting errors, and the time-alignment and physical-reference limitations in Sect. 4.3 apply.',
93: 'The historical CD-Ygb replay also exercised the ground-matching workflow. That replay is retained as an implementation diagnostic and is excluded from the European 12-station statistics. Numerical agreement with archived outputs establishes repeatability for the tested inputs and configuration; it does not establish independent temperature accuracy, correct source-time interpretation or equivalence to the corrected station evaluation in Sects. 4.2–4.3.',
95: '5.1 Sensitivity to validation support',
96: 'The 10 K filter uses the same reference observations against which accuracy is reported, so the resulting RMSEs are conditional on sample retention (Fig. 9). At EVO, the range-only and residual-screened comparisons use the same configuration and 11:00–16:00 UTC window. In Europe, keeping the 0–60 °C condition but omitting the residual filter gives mean station RMSEs of 6.248 K for shaded soil and 4.111 K for canopy at the same 12 stations, with 1015 month–hour groups and 8108 contributing instantaneous pairs. Adding the joint 10 K condition reduces these to 4.014 and 3.626 K on 778 groups and 5472 pairs. This change is caused by selection and changed aggregation support, not by a change in inversion parameters. Range screening also excludes real cold-season observations and does not describe year-round product performance. The post hoc station subset adds another selection effect: including IT-TrF and FR-EM2 gives 14-station RMSEs of 3.957 and 3.854 K under the same hour, aggregation and joint-filter rules. Removing the two sites therefore does not improve both components. Full-station, range-only and residual-screened results are retained together to make these effects explicit.',
98: 'Figure 9. Sensitivity of month–hour RMSE to reference-based residual screening at 11:00–16:00 UTC. Light bars apply the 0–60 °C range condition only; dark bars additionally require both instantaneous component–reference differences to be ≤10 K. Panel (a) shows EVO sunlit soil, background soil and canopy; background soil is compared with sunlit-soil radiometry and the canopy sample follows the sunlit-soil scheme. Panel (b) shows shaded soil and canopy at the same 12 European stations. Station RMSEs are averaged equally in panel (b). The filters change retained observations and monthly support; bar differences are not algorithm improvements.',
112: 'Second, coarse footprints can include irrigation, water, urban surfaces, ecotones and complex terrain that a canopy–soil model represents incompletely. Direct component observations remain limited to the 2017 EVO open-woodland case. EVO background-soil comparisons use sunlit-soil radiometry, whereas European shaded-soil and canopy comparisons use subsurface soil temperature and air temperature. None provides independent validation of the background-soil aggregate. The 10 K filter conditions reported errors on the observed references, and the European 12-station subset was chosen after inspecting errors. These limitations, together with unresolved source-time conventions, prevent a spatially uniform accuracy claim. A product-level evaluation must extract the corresponding regional grid values using matched months, hours and reference screening. Numerical replay cannot establish physical validity or independence from parameter selection. Per-pixel sample counts, component-separability diagnostics and uncertainty estimates are needed across the full archive.',
116: 'LS4T-MSG provides 707 monthly files for August 2017–December 2025 at seven nominal UTC hours, describing canopy and background-soil temperatures with diagnostic sunlit- and shaded-soil states. The station evaluation retains hour-of-day information by calculating paired monthly means separately at 11:00–16:00 UTC. Under joint 0–60 °C and 10 K screening, EVO sunlit-soil and canopy RMSEs are 1.883 and 3.427 K across 30 month–hour pairs; background soil differs from the sunlit-soil radiometry by an RMSE of 2.929 K. At the post hoc subset of 12 European stations, mean station RMSEs are 4.014 K for shaded soil against soil probes and 3.626 K for canopy against air temperature. These results describe screened station-mode comparisons, with different physical references in the two domains, and do not establish accuracy of the archived regional product.',
117: 'The contribution is a monthly component-temperature record retaining time-of-day structure within each month. The revised validation separates direct sunlit-soil and canopy radiometry, cross-component background-soil comparison, and indirect meteorological consistency. Full-station and range-only sensitivities show how sample selection affects the reported errors. Regional product accuracy, the background-soil aggregate and source-time alignment remain insufficiently established. Resolving input decoding, daylight screening and the 2022 viewing geometry, and supplying consistent sampling metadata, are necessary before broad quantitative use of a corrected release. The interannual examples describe variability in the available retrievals and do not establish climate trends.'}
    for i,text in texts.items():replace(doc.paragraphs[i],text)
    # Clarify unresolved source-time conventions without claiming they were fixed.
    before_image=doc.paragraphs[88]
    p=before_image.insert_paragraph_before('Ground matching retains the existing interpretation of each source TIMESTAMP_START as UTC and uses the nearest record within ±30 min. The source-specific UTC offset and interval convention still require verification: a portal’s UTC preview axis does not establish the convention of a downloaded CSV. The 10:00 product slot is excluded from the principal comparison to use the same six-hour window at EVO and the European sites; this is an analysis choice rather than evidence that 10:00 observations are invalid. Comparisons including 10:00 are retained in the reproduction package. The post hoc exclusion of IT-TrF and FR-EM2 is assessed against the complete 14-station results in Sect. 5.1.')
    p.style=doc.styles['Normal']
    # Match surrounding body spacing rather than the template's default double spacing.
    source_ppr=doc.paragraphs[87]._p.pPr
    if source_ppr is not None:
        if p._p.pPr is not None:p._p.remove(p._p.pPr)
        p._p.insert(0,deepcopy(source_ppr))
    # Replace figures by their original paragraph objects, unaffected by inserted text.
    for no,paragraph,name in [(5,76,'figure05_evo_diurnal'),(6,81,'figure06_evo_scatter'),(7,84,'figure07_evo_hourly'),(8,88,'figure08_europe12'),(9,97,'figure09_filter_sensitivity')]:
        target=original.paragraphs[paragraph]
        # Resolve the unique original relationship in the edited document.
        rid=target._p.xpath('.//a:blip')[0].get(qn('r:embed'))
        matches=[a for a in doc.paragraphs if any(b.get(qn('r:embed'))==rid for b in a._p.xpath('.//a:blip'))]
        assert len(matches)==1
        a=matches[0];a.clear();a.add_run().add_picture(str(ROOT/'figures'/(name+'.png')),width=Inches(6.65))
        a.alignment=WD_ALIGN_PARAGRAPH.CENTER;a.paragraph_format.keep_with_next=True
    # Remove three inventory rows: the non-European replay site and two excluded European sites.
    for row in list(doc.tables[0].rows)[1:]:
        if row.cells[0].text in {'CD-Ygb','IT-TrF','FR-EM2'}:row._tr.getparent().remove(row._tr)
    assert len(doc.tables[0].rows)==13
    t=doc.tables[1]
    replacements={(1,1):'Identical EURO/IODC UTC timestamps; daily EURO LAI. The archived regional reader applies uint16 raw/100 + 273.15 K. Corrected station evaluation restores signed LST values and uses a common physical input mask; zero remains missing. LAI uses raw/1000.',
        (4,1):'Archived regional windows: 3 × 3 then 5 × 5, with nearest-edge padding. Corrected station evaluation: central 5 × 5 windows at both stages, without edge padding. Determinant threshold 10⁻⁸; at least 40% valid paired neighbors.',
        (5,2):'Corrected station evaluation uses λ = 1000, hotspot = 0.25 and two 5 × 5 stages, with physical Planck units. Its scores do not validate the differently configured regional archive. The archive-wide adjustment magnitude is unquantified.',
        (6,2):'Corrected station predictions require all four outputs within 250–350 K before joint 0–60 °C and 10 K reference-based evaluation screening. Regional monthly files lack per-pixel counts and quality arrays. Reference-based screening is not a production quality flag.'}
    for (r,c),text in replacements.items():
        cell=t.cell(r,c);replace(cell.paragraphs[0],text)
        for extra in cell.paragraphs[1:]:extra._p.getparent().remove(extra._p)
    # Keep data-availability provenance consistent with the revised figures.
    p=next(a for a in doc.paragraphs if a.text.startswith('The collection comprises 707 monthly HDF5 files:'))
    replace(p,p.text.replace('Figure reproduction uses archived temperatures, while the replay tests execute the retrieval separately; neither establishes a corrected historical archive.',
        'Figures 5–9 use the corrected station predictions and matched month–hour tables, including both EVO soil schemes, the European 12-station subset, and full-station and filter sensitivities. Figures 1–4 and 10–11 retain their existing geometry and regional-archive sources. Neither the revised station evaluation nor the replay tests establishes a corrected regional historical archive.'))
    # Keep formulas untouched and all figure/caption counts stable.
    assert before==[etree.tostring(e) for e in doc._element.xpath('.//m:oMath')]
    assert len(doc.inline_shapes)==11
    captions=[a.text for a in doc.paragraphs if re.match(r'^Figure \d+\.',a.text)]
    assert len(captions)==11
    full='\n'.join(a.text for a in doc.paragraphs)
    for obsolete in ['RMSEs of 1.89 K','across 35 month–hour','all 15 stations','pooling 11:00','mean RMSE is 9.15','641 raw pairs','644 for canopy']:
        assert obsolete not in full,obsolete
    OUTPUT.parent.mkdir(exist_ok=True);doc.save(OUTPUT)
    check=Document(OUTPUT);assert len(check.inline_shapes)==11 and len(check.tables[0].rows)==13
    assert before==[etree.tostring(e) for e in check._element.xpath('.//m:oMath')]
    audit=dict(status='structural_checks_passed_pending_render',source=str(SOURCE),backup=str(backup),output=str(OUTPUT),
        modified_paragraphs=sorted(texts),figures_replaced=[5,6,7,8,9],equations_preserved=len(before),figures=11,station_rows=12,
        source_sha256=hashlib.sha256(backup.read_bytes()).hexdigest(),output_sha256=hashlib.sha256(OUTPUT.read_bytes()).hexdigest())
    (ROOT/'document_edit_audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2),encoding='utf8')
    (ROOT/'修订记录.md').write_text('# 验证口径更新\n\n更新现有v6，不建立v7。EVO主比较为光照土壤/冠层，并增加背景土壤对光照土壤实测的诊断；欧洲采用12站阴影土壤/冠层。全部主结果为11—16 UTC逐小时月均，联合0—60°C与10 K筛选。\n\n同步摘要、2.4节、表1、表2、4.1—4.3节、5.1节、局限性、结论和数据来源说明，重绘图5—9；保留其他区域产品图和全部公式。图9用范围筛选与联合残差筛选对照，替换已不适用的历史方法比较。原14站结果和事后排除说明保留。\n\n未开展新反演或区域重生产。通讯作者、作者贡献、公开归档与产品级验证等原有事项仍待完成；本次不宣称达到投稿条件。\n',encoding='utf8')
    print(json.dumps(audit,ensure_ascii=False,indent=2))

if __name__=='__main__':main()
